   481|export async function executeApprovedAction(id: string): Promise<ApprovedAction | null> {
   482|  const list = await readActions();
   483|  const idx = list.findIndex((a) => a.id === id);
   484|  if (idx === -1) return null;
   485|  const current = list[idx];
   486|  if (current.status !== 'approved') {
   487|    throw new Error(`Action ${id} is not approved (status=${current.status}).`);
   488|  }
   489|  const startedAt = Date.now();
   490|  list[idx] = { ...current, status: 'executing', updatedAt: startedAt };
   491|  await writeActions(list);
   492|  await appendAudit({
   493|    actionId: id,
   494|    kind: current.kind,
   495|    event: 'execute_started',
   496|    affected: current.affected,
   497|    approver: current.approver,
   498|    result: 'started',
   499|    detail: `Executing: ${current.title}`,
   500|  });
   501|
   502|  let result: ApprovedActionResult;
   503|  try {
   504|    if (current.payload.kind === 'file_patch') {
   505|      // Phone cannot write files directly. Owner has approved the diff; the apply
   506|      // is performed manually by the workspace promoter (Rork sync / git push).
   507|      // We mark the action executed with a clear summary so audit reflects state.
   508|      result = {
   509|        ok: true,
   510|        httpStatus: 200,
   511|        summary: `File patch approved for manual apply :: ${current.payload.filePath}`,
   512|        detail:
   513|          'Approved patches are written through the GitHub commit action; the phone never edits files directly.',
   514|        finishedAt: Date.now(),
   515|      };
   516|    } else if (current.payload.kind === 'github_commit') {
   517|      const res = await postDeveloperDeployAction({
   518|        action: 'github_commit_approved_patches',
   519|        confirm: true,
   520|        reason: current.reason,
   521|        input: {
