    27|import { supabase } from '@/lib/supabase';
    28|
    29|// ─── Types ───────────────────────────────────────────────────────────
    30|
    31|type BrainStatus = 'healthy' | 'degraded' | 'stale' | 'broken' | 'unverified';
    32|
    33|interface DashboardData {
    34|  brain: {
    35|    overallStatus: BrainStatus;
    36|    decision: string;
    37|    commitMatch: boolean;
    38|    commits: { github: string | null; render: string | null; production: string | null };
    39|    platforms: Array<{ platform: string; ok: boolean; configured: boolean; error: string | null; details: Record<string, unknown> }>;
    40|    deployInProgress: boolean;
    41|    latestDeploy: { id: string | null; status: string | null; duration: number | null };
    42|    credentials: { total: number; valid: number; missing: number; failed: number };
    43|    errors: string[];
    44|    blockers: string[];
    45|    nextAction: string;
    46|    autoRepairAvailable: boolean;
    47|    ownerApprovalRequired: boolean;
    48|  };
    49|  evidence: {
    50|    endpoints: Array<{ name: string; ok: boolean; status: number | null; latencyMs: number; error: string | null }>;
    51|    commitMatch: boolean;
    52|    commits: Array<{ source: string; shortSha: string | null; error: string | null }>;
    53|    allEndpointsOk: boolean;
    54|    healthStatus: string | null;
    55|  };
    56|  credentials: {
    57|    summary: { total: number; valid: number; missing: number; failed: number };
    58|    gaps: string[];
    59|    recommendations: string[];
    60|  };
    61|  timestamp: string;
    62|}
    63|
    64|// ─── Styles ───────────────────────────────────────────────────────────
    65|
    66|const COLORS = {
