const fs = require('fs');
const https = require('https');
const TOKEN = fs.readFileSync('/tmp/owner_token.txt', 'utf8').trim();
const API_BASE = 'https://api.ivxholding.com';

function commitFile(path, content, message) {
  return new Promise((resolve) => {
    const payload = JSON.stringify({
      action: 'github_commit_file',
      confirm: true,
      confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
      input: { path, content, message }
    });
    const req = https.request({
      hostname: 'api.ivxholding.com',
      path: '/api/ivx/developer-deploy/action',
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + TOKEN,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      },
      timeout: 60000
    }, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve({status: res.statusCode, body: JSON.parse(data)}); } catch(e) { resolve({status: res.statusCode, raw: data.slice(0,2000)}); }
      });
    });
    req.on('error', err => resolve({error: err.message}));
    req.on('timeout', () => { req.destroy(); resolve({error: 'timeout'}); });
    req.write(payload);
    req.end();
  });
}

(async () => {
  const dashboardContent = fs.readFileSync('expo/components/DeploymentDashboard.tsx', 'utf8');
  const planContent = fs.readFileSync('.rork/plans/ivx-ia-final-certification-terminal-stat_1784657316341.plan.md', 'utf8');

  console.log('Committing DeploymentDashboard.tsx...');
  const r1 = await commitFile('expo/components/DeploymentDashboard.tsx', dashboardContent, 'feat(dashboard): manual Redeploy button for owner-triggered Render builds');
  console.log('Dashboard commit:', r1.status, r1.body?.commitSha || r1.body?.error || r1.raw || 'no sha');

  console.log('Committing plan.md...');
  const r2 = await commitFile('.rork/plans/ivx-ia-final-certification-terminal-stat_1784657316341.plan.md', planContent, 'docs(plan): update certification status with honest Phase 16 failure and build-pipeline blocker');
  console.log('Plan commit:', r2.status, r2.body?.commitSha || r2.body?.error || r2.raw || 'no sha');
})();
